#include <stdio.h>
#include <string.h>

double power(double base, int exponent)
{
    double result = 1.0;
    for (int i = 0; i < exponent; i++) {
        result *= base;
    }
    return result;
}

int main(void)
{
    char line[200];
    while (fgets(line, sizeof line, stdin) != NULL) {
        line[strcspn(line, "\r\n")] = '\0';
        if (line[0] == '\0') {
            continue;
        }
        double a = 0.0, b = 0.0;
        char op = 0;
        if (sscanf(line, "%lf %c %lf", &a, &op, &b) != 3) {
            printf("Could not read: %s\n", line);
            continue;
        }
        switch (op) {
        case '+': printf("= %g\n", a + b); break;
        case '-': printf("= %g\n", a - b); break;
        case '*': printf("= %g\n", a * b); break;
        case '/':
            if (b == 0.0) printf("Cannot divide by zero\n");
            else printf("= %g\n", a / b);
            break;
        case '%':
            if ((long long)b == 0) printf("Cannot divide by zero\n");
            else printf("= %lld\n", (long long)a % (long long)b);
            break;
        case '^':
            if (b < 0 || b > 63 || b != (int)b) printf("Bad power\n");
            else printf("= %g\n", power(a, (int)b));
            break;
        default:
            printf("Unknown operator: %c\n", op);
            break;
        }
    }
    return 0;
}
